"""services.home_dns.snippet — the household Caddy block (LUM-331)."""

from __future__ import annotations

import pytest
from services.home_dns.snippet import render

HID = "kq7f3r2abcdefghijklmnopqrs"
BEARER = "b" * 43
URL = "https://dns.homes.lumogis.app"

GOLDEN = (
    "# Generated by Lumogis (LUM-331, Secure address). Do not edit: it is\n"
    "# rewritten when the secure address is turned on, changed or off.\n"
    f"{HID}.homes.lumogis.app {{\n"
    "\ttls {\n"
    "\t\tdns acmedns {\n"
    f"\t\t\tusername {HID}\n"
    f"\t\t\tpassword {BEARER}\n"
    f"\t\t\tsubdomain {HID}\n"
    f"\t\t\tserver_url {URL}\n"
    "\t\t}\n"
    "\t}\n"
    "\timport lumogis_routes\n"
    "}\n"
)


@pytest.fixture(autouse=True)
def _zone(monkeypatch):
    monkeypatch.delenv("LUMOGIS_HOME_DNS_ZONE", raising=False)


def test_golden() -> None:
    assert render(HID, BEARER, URL) == GOLDEN


def test_staging_adds_only_the_ca_line() -> None:
    staged = render(HID, BEARER, URL, staging=True)
    extra = set(staged.splitlines()) - set(GOLDEN.splitlines())
    assert extra == {"\t\tca https://acme-staging-v02.api.letsencrypt.org/directory"}


def test_non_443_port_adds_explicit_redirect() -> None:
    out = render(HID, BEARER, URL, https_port=8443)
    assert out.startswith(GOLDEN)
    assert out[len(GOLDEN) :] == (
        f"http://{HID}.homes.lumogis.app {{\n"
        f"\tredir https://{HID}.homes.lumogis.app:8443{{uri}} permanent\n"
        "}\n"
    )


@pytest.mark.parametrize(
    "household_id,bearer,url,port",
    [
        ("evil.homes.lumogis.app}\nimport /etc/passwd", BEARER, URL, 443),
        (HID + "\n", BEARER, URL, 443),
        (HID, BEARER + "}", URL, 443),
        (HID, BEARER + "\n", URL, 443),
        (HID, "short", URL, 443),
        (HID, BEARER, "https://dns.example.test/}\nimport x", 443),
        (HID, BEARER, "http://dns.example.test", 443),
        (HID, BEARER, URL, 0),
        (HID, BEARER, URL, 70000),
    ],
)
def test_rejects_invalid_input(household_id, bearer, url, port) -> None:
    with pytest.raises(ValueError):
        render(household_id, bearer, url, https_port=port)
